556	      type: 'error', source: 'mcp', tool: toolName,
557	      blocked: false,
558	      details: error instanceof Error ? error.message : 'Internal error',
559	      apiKeyPrefix: apiKey?.substring(0, 12),
560	      durationMs: Date.now() - requestStart,
561	    });
562	
563	    // Classify 503 cause and enrich error response
564	    const classified = classify503Cause(error instanceof Error ? error : String(error), toolName);
565	    const statusCode = classified.cause === 'circuit_breaker_open' || classified.cause === 'memory_pressure' ? 503 : 500;
566	    if (classified.retry_after_ms) {
