// TOOL CLASSIFICATION
// ============================================================================

const HEAVY_TOOLS = new Set([
  'gravito.reviewContent',
  'gravito.governanceAudit',
  'gravito.checkCompliance',
  'gravito.runCreativeIntegrity',
  'gravito.composeEmail',
]);

const DISCOVERY_METHODS = new Set([
  'tools/list',
  'initialize',
  'resources/list',
  'prompts/list',
]);

const POLL_METHODS = new Set([
  'jobs/get',
  'jobs/status',
]);

export type BucketType = 'discovery' | 'standard' | 'heavy' | 'jobs_poll';

export function classifyRequest(method: string, toolName?: string): BucketType {
  if (DISCOVERY_METHODS.has(method)) return 'discovery';
  if (POLL_METHODS.has(method)) return 'jobs_poll';
  if (toolName && HEAVY_TOOLS.has(toolName)) return 'heavy';
  return 'standard';
}

// ============================================================================
// KEY HASHING (for headers — never expose raw IDs)
// ============================================================================

export function hashKey(key: string): string {
  return createHash('sha256').update(key).digest('hex').substring(0, 12);
}

// ============================================================================
// PUBLIC API
// ============================================================================

export interface RateLimitResult {
  allowed: boolean;
  retryAfterMs?: number;
  limit: string;
  remaining: number;
  bucket: BucketType;
  tier: PlanTier;
  keyHash: string;
  keyType: 'customer' | 'ip';
}

/**
 * Check rate limit for an MCP request.
 * 
 * @param apiKey - The API key or customer ID (or 'anonymous')
 * @param clientIp - Client IP address
 * @param toolName - Tool being called (for tools/call)
 * @param method - MCP method (tools/call, tools/list, etc.)
 */
export function checkRateLimit(
  apiKey: string,
  clientIp: string,
  toolName: string,
  method?: string,
): RateLimitResult {
  const bucketType = classifyRequest(method || 'tools/call', toolName);
  const customerId = apiKey || 'anonymous';
  const tier = getCustomerTier(customerId);
  const limits = TIER_LIMITS[tier];
  const keyHash = hashKey(customerId);

  // Discovery: keyed by IP (unauthenticated)
  if (bucketType === 'discovery') {
    const bucket = getBucket(`disc:${clientIp}`, limits.discoveryPerMinute, limits.discoveryPerMinute / 60);
    if (!consumeToken(bucket)) {
      log.warn(`[Rate Limit] IP ${clientIp} exceeded discovery limit (${limits.discoveryPerMinute}/min)`);

