mcpRouterV2.post('/tools/list', (_req: Request, res: Response) => {
  ensureServerInitialized();
  const activeTools = filterActiveTools(ALL_TOOLS);
  const tools = activeTools.map(tool => {
    const schema = tool.inputSchema as unknown as Record<string, unknown>;
    const isZod = (s: unknown): s is z.ZodTypeAny => !!s && typeof (s as z.ZodTypeAny).parse === 'function';
    return { name: tool.name, description: tool.description, inputSchema: isZod(schema) ? zodToJsonSchema(schema) : schema };
  });
  res.json({ tools, server_name: GRAVITO_MCP_SERVER_NAME, version: '1.0.0', auth: AUTH_METADATA });
});

// ============================================================================
// USAGE STATS (authenticated)
// ============================================================================

mcpRouterV2.get('/usage', authenticateMCP, async (req: Request, res: Response) => {
  try {
    const period = (req.query.period as string) || '24h';
    const since = new Date();
    switch (period) {
      case '1h': since.setHours(since.getHours() - 1); break;
      case '24h': since.setHours(since.getHours() - 24); break;
      case '7d': since.setDate(since.getDate() - 7); break;
      case '30d': since.setDate(since.getDate() - 30); break;
      default: since.setHours(since.getHours() - 24);
    }
    const stats = await getUsageStats(since);
    res.json({ period, since: since.toISOString(), ...stats });
  } catch (error: unknown) {
    generalLog.error('[MCP Usage] Error:', error);
    res.status(500).json({ error: 'Failed to retrieve usage stats' });
  }
});

// ============================================================================
// ASYNC JOB STATUS POLLING (authenticated)
// ============================================================================

mcpRouterV2.get('/jobs/:jobId', async (req: Request, res: Response) => {
  const { jobId } = req.params;
  const apiKey = extractApiKey(req);

  if (!apiKey) {
    return res.status(401).json({ error: 'Authentication required. Provide API key via Authorization: Bearer <key> header.' });
  }

  const isValid = await validateApiKey(apiKey);
  if (!isValid) {
    return res.status(403).json({ error: 'Invalid API key.' });
  }

  const job = getJob(jobId, apiKey);
  if (!job) {
    return res.status(404).json({ error: `Job ${jobId} not found or access denied.` });
  }

  const origin = `${req.protocol}://${req.get('host')}`;
  const response = buildJobResponse(job, origin);

  // Set appropriate cache + Retry-After headers per job state
  if (job.status === 'completed') {
    res.setHeader('Cache-Control', 'private, max-age=300');
    return res.status(200).json(response);
  } else if (job.status === 'failed') {
    res.setHeader('Cache-Control', 'private, max-age=60');
    return res.status(200).json(response);
  } else {
    // Still pending or running — tell client when to poll again
    const retryAfter = response.retry_after_s || (job.status === 'queued' ? 3 : 2);
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Retry-After', retryAfter.toString());
    return res.status(200).json(response);
  }
});

// ============================================================================
// JOB MANAGEMENT ENDPOINTS (Nervous System Fix 5)
// ============================================================================

// List jobs for authenticated client with optional status filter
mcpRouterV2.get('/jobs', async (req: Request, res: Response) => {
  const apiKey = extractApiKey(req);
  if (!apiKey) {
    return res.status(401).json({ error: 'Authentication required.' });
  }
  const isValid = await validateApiKey(apiKey);
  if (!isValid) {
    return res.status(403).json({ error: 'Invalid API key.' });
  }

  const status = req.query.status as JobStatus | undefined;
  const limit = Math.min(parseInt(req.query.limit as string) || 20, 100);
  const offset = parseInt(req.query.offset as string) || 0;

  const result = listJobs(apiKey, {
    status,
    limit,
    offset,
  });

  res.json({
    ...result,
    jobs: result.jobs.map(j => ({
      id: j.id,
      tool: j.toolName,
      status: j.status,
      created_at: j.createdAt,
      started_at: j.startedAt,
      completed_at: j.completedAt,
      elapsed_ms: j.completedAt ? j.completedAt - j.createdAt : j.startedAt ? Date.now() - j.startedAt : undefined,
      has_result: j.status === 'completed' && !!j.result,
      has_webhook: !!j.webhook,
    })),
    queue_stats: getAsyncQueueStats(),
    timestamp: Date.now(),
  });
});

// Cancel a pending/running job
mcpRouterV2.delete('/jobs/:jobId', async (req: Request, res: Response) => {
  const { jobId } = req.params;
  const apiKey = extractApiKey(req);
  if (!apiKey) {
    return res.status(401).json({ error: 'Authentication required.' });
  }
  const isValid = await validateApiKey(apiKey);
  if (!isValid) {
    return res.status(403).json({ error: 'Invalid API key.' });
  }

  const result = cancelJob(jobId, apiKey);
  if (result.cancelled) {
    return res.json({ cancelled: true, job_id: jobId });
  } else {
    return res.status(result.reason === 'Job not found' ? 404 : 409).json({
      cancelled: false,
      reason: result.reason,
      job_id: jobId,
    });
  }
});

// ============================================================================
// ULTRA-LIGHTWEIGHT PING (for keep-alive / cold-start prevention)
// Returns in <1ms, no auth, no computation. Callers should hit this before
// making tool calls to ensure the machine is warm.
// ============================================================================

mcpRouterV2.get('/ping', (_req: Request, res: Response) => {
  res.status(200).json({ pong: true, ts: Date.now() });
});

// ============================================================================
// SELF-PING KEEP-ALIVE
// Pings our own health endpoint every 25 seconds to prevent Fly.io from
// recycling the machine. This eliminates cold-start 503s.
// ============================================================================

let keepAliveInterval: NodeJS.Timeout | null = null;

export function startMCPKeepAlive(): void {
  if (keepAliveInterval) return;

  const KEEP_ALIVE_INTERVAL_MS = 25_000; // 25 seconds

  keepAliveInterval = setInterval(async () => {
    try {
      // Use the app's own health endpoint to keep the machine warm
      const port = process.env.PORT || 3000;
      const resp = await fetch(`http://localhost:${port}/api/healthz`, {
        method: 'GET',
        signal: AbortSignal.timeout(5000),
      });
      if (!resp.ok) {
        generalLog.warn(`[KeepAlive] Health ping returned ${resp.status}`);
      }
    } catch (err) {
      // Silently ignore — if the server is down, the keep-alive doesn't matter
    }
  }, KEEP_ALIVE_INTERVAL_MS);

  // Don't let the keep-alive prevent process exit
  keepAliveInterval.unref();

  generalLog.info(`[KeepAlive] MCP keep-alive started (every ${KEEP_ALIVE_INTERVAL_MS / 1000}s)`);
}

export function stopMCPKeepAlive(): void {
  if (keepAliveInterval) {
    clearInterval(keepAliveInterval);
    keepAliveInterval = null;
    generalLog.info('[KeepAlive] MCP keep-alive stopped');
  }
}

export default mcpRouterV2;

