const mcpRouterV2 = Router();

// ============================================================================
// JSON-RPC HANDLER
// Split: initialize + tools/list are unauthenticated (MCP spec: auth is OPTIONAL)
//        tools/call requires API key authentication
// This enables MCP CLI discovery without OAuth while protecting tool execution.
// ============================================================================

interface EnrichedResult {
    content: { type: string; text: string }[];
}

mcpRouterV2.post('/', async (req: Request, res: Response) => {
  const requestStart = Date.now();
  const clientIp = req.ip || req.socket.remoteAddress || 'unknown';
  const userAgent = req.headers['user-agent'] || 'unknown';
  const requestId = `mcp-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const correlationId = extractCorrelationId(req);
  res.setHeader('x-correlation-id', correlationId);
  res.setHeader('x-gravito-request-id', requestId);

  try {
    ensureServerInitialized();

    const { method, params, id } = req.body || {};

    // Structured observability log for every MCP request
    generalLog.info(`[MCP] ${requestId} method=${method || 'unknown'} ip=${clientIp} ua=${userAgent.slice(0, 60)} hasAuth=${!!req.headers.authorization || !!req.headers['x-api-key']}`);

    // ── READ-ONLY METHODS (no auth required) ──
    // Per MCP spec, initialize and tools/list are discovery operations.
    // Allowing them unauthenticated enables CLI tool listing and server discovery.
    switch (method) {
      case 'initialize':
        generalLog.info(`[MCP] ${requestId} initialize completed in ${Date.now() - requestStart}ms`);
        return res.json({
          jsonrpc: '2.0', id,
          result: {
            protocolVersion: '2024-11-05',
            capabilities: { tools: { listChanged: false } },
            serverInfo: { name: GRAVITO_MCP_SERVER_NAME, version: '1.0.0' },
          },
        });

      case 'tools/list': {
        const activeTools = filterActiveTools(ALL_TOOLS);
        const toolsList = activeTools.map(tool => {
              const schema = tool.inputSchema as unknown as Record<string, unknown>;
              const isZod = (s: unknown): s is z.ZodTypeAny => !!s && typeof (s as z.ZodTypeAny).parse === 'function';
              return { name: tool.name, description: tool.description, inputSchema: isZod(schema) ? zodToJsonSchema(schema) : schema };
        });
        generalLog.info(`[MCP] ${requestId} tools/list returned ${toolsList.length} tools (${ALL_TOOLS.length - activeTools.length} quarantined) in ${Date.now() - requestStart}ms`);
        return res.json({
          jsonrpc: '2.0', id,
          result: { tools: toolsList },
        });
      }

      case 'notifications/initialized':
        // MCP protocol notification — client confirms initialization complete
        generalLog.info(`[MCP] ${requestId} notifications/initialized ack in ${Date.now() - requestStart}ms`);
        return res.json({ jsonrpc: '2.0', id, result: {} });

      case 'tools/call': {
        // ── AUTHENTICATED: tools/call requires API key ──
        const apiKey = extractApiKey(req);
        const hasServerKey =
          !!process.env.BUILT_IN_FORGE_API_KEY?.trim() ||
          !!process.env.GRAVITO_API_KEY?.trim() ||
          !!process.env.GravitoAPI?.trim();
        if (process.env.NODE_ENV !== 'development' || hasServerKey) {
          if (!apiKey) {
            return res.status(401).json({
              jsonrpc: '2.0', id,
              error: { code: -32000, message: 'Authentication required for tools/call. Provide API key via Authorization: Bearer <key> header or X-API-Key header.' },
            });
          }

          const isValid = await validateApiKey(apiKey);
          if (!isValid) {
            return res.status(403).json({
              jsonrpc: '2.0', id,
              error: { code: -32001, message: 'Invalid API key provided.' },
            });
          }
        }

        // MCP protocol uses 'arguments', but some clients send 'args' — support both
        const { name, arguments: mcpArguments, args: mcpArgs, webhook } = params || {};
        const rawArgs = mcpArguments || mcpArgs || {};
        const normalizedArgs = normalizeArgs(rawArgs, name);

        if (!name || typeof name !== 'string') {
          return res.status(400).json({ jsonrpc: '2.0', id, error: { code: -32602, message: 'Invalid params: "name" is a required string.' } });
        }

        const tool = ALL_TOOLS.find(t => t.name === name);
        if (!tool) {
          return res.status(404).json({ jsonrpc: '2.0', id, error: { code: -32601, message: `Tool not found: ${name}` } });
        }

        // ── RATE LIMITING ──
        // FIX: checkRateLimit takes (apiKey, clientIp, toolName, method?)
        // FIX: RateLimitResult uses 'allowed' not 'success', 'retryAfterMs' not 'retryAfter', no 'reset' field
        const rateLimitResult = checkRateLimit(apiKey || 'anonymous', clientIp, name);
        res.setHeader('X-RateLimit-Limit', String(rateLimitResult.limit));
        res.setHeader('X-RateLimit-Remaining', String(rateLimitResult.remaining));
        // No 'reset' field in RateLimitResult — use estimated retry time
        res.setHeader('X-RateLimit-Reset', String(Math.ceil(Date.now() / 1000) + 60));

        if (!rateLimitResult.allowed) {
          const retryAfterSec = Math.ceil((rateLimitResult.retryAfterMs || 5000) / 1000);
          res.setHeader('Retry-After', String(retryAfterSec));
          return res.status(429).json({
            jsonrpc: '2.0', id,
            error: {
              code: -32005,
              message: `Rate limit exceeded for tool ${name}. Please try again later.`,
              data: getRateLimitStatus(apiKey || clientIp, name),
            },
          });
        }

        // ── ASYNC EXECUTION (if applicable) ──
        // FIX: shouldUseAsync 2nd arg is boolean (preferAsync from header), NOT the args object
        const preferAsync = req.headers['x-prefer-async'] === 'true';
        if (shouldUseAsync(name, preferAsync)) {
          // FIX: createAsyncJob takes (toolName, args, context: CreateJobOptions), not 4 separate args
          const { job: asyncJob, headers: jobHeaders } = createAsyncJob(name, normalizedArgs, {
            apiKey: apiKey || 'anonymous',
            clientIp,
            userAgent,
            callbackUrl: webhook?.url || webhook?.callback_url,
            callbackSecret: webhook?.secret,
            callbackHeaders: webhook?.headers,
          });
          const origin = `${req.protocol}://${req.get('host')}`;
          // FIX: pass the actual job object (not the wrapper) to buildJobResponse
          const response = buildJobResponse(asyncJob, origin);
          // Set job headers
          for (const [key, value] of Object.entries(jobHeaders)) {
            res.setHeader(key, value);
          }
          res.setHeader('Retry-After', response.retry_after_s?.toString() || '5');

          // Start async execution in background.
          // Mirror the SYNC path's flag-gated, fail-open tenant resolution (this
          // tool is not normally routed async, but keep the ctx consistent).
          let asyncAuthenticatedTenant: { tenantId: string; source: string } | undefined;
          if (isFeatureEnabled('CANONICAL_VERDICT_RECEIPT_ENABLED')) {
            try { asyncAuthenticatedTenant = await resolveGovernedAuthenticatedTenant(req); } catch { asyncAuthenticatedTenant = undefined; }
          }
          executeTool(name, normalizedArgs, { apiKey, clientIp, userAgent, correlationId, requestId, authenticatedTenant: asyncAuthenticatedTenant })
            .then(result => {
              asyncJob.status = 'completed';
              asyncJob.result = result;
              asyncJob.completedAt = Date.now();
            })
            .catch(err => {
              asyncJob.status = 'failed';
              asyncJob.error = err instanceof Error ? err.message : String(err);
              asyncJob.completedAt = Date.now();
            });

          return res.status(202).json(response);
        }

        // ── GATE ENFORCEMENT (Nervous System Fix 4) ──
        // FIX: classifyGovernanceRequirement takes (args) not (name, args)
        // FIX: enforceGate takes (toolName, args, options) not (surface, options)
        // FIX: GateEnforcementResult uses 'allowed' not 'approved'
        try {
          // Extract approval_token from args so gate can validate it
          const approvalToken = (normalizedArgs as Record<string, unknown>).approval_token as string | undefined;
          const gateResult: GateEnforcementResult = enforceGate(name, normalizedArgs, {
            approvalToken,
          });
          if (!gateResult.allowed) {
            const envelope = buildGovernanceEnvelope(gateResult);
            return res.status(403).json({ jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: JSON.stringify(envelope) }] } });
          }
        } catch (gateError) {
          generalLog.warn(`[MCP v2] Gate enforcement error (non-fatal, proceeding):`, gateError);
          // Non-fatal: proceed with tool execution even if gate check fails
        }

        // ── TRUSTED TENANT RESOLUTION (flag-gated, fail-open) ──
        // Only when CANONICAL_VERDICT_RECEIPT_ENABLED — default-OFF ⇒ no
        // resolution runs ⇒ authenticatedTenant undefined ⇒ byte-identical ctx.
        // Spoof-proof: resolveInferenceTenant ignores x-gravito-tenant for a
        // provisioned tenant key. Fail-open: any error → undefined.
        let authenticatedTenant: { tenantId: string; source: string } | undefined;
        if (isFeatureEnabled('CANONICAL_VERDICT_RECEIPT_ENABLED')) {
          try { authenticatedTenant = await resolveGovernedAuthenticatedTenant(req); } catch { authenticatedTenant = undefined; }
        }

        // ── SYNCHRONOUS EXECUTION with TIMEOUT ──
        const toolTimeoutMs = getToolTimeout(name);
        const executionPromise = executeTool(name, normalizedArgs, { apiKey, clientIp, userAgent, correlationId, requestId, authenticatedTenant });

        const outcome = await withTimeout(executionPromise, toolTimeoutMs, name);

        if (outcome.timedOut) {
          recordToolExecution(name, outcome.durationMs, true, false);
          generalLog.warn(`[MCP v2] Tool ${name} timed out after ${outcome.durationMs}ms (limit: ${toolTimeoutMs}ms)`);

          logUsage({
            apiKey, ipAddress: clientIp, toolName: name, method: 'tools/call',
            success: false, errorMessage: `Tool execution timed out after ${outcome.durationMs}ms`,
            responseTimeMs: outcome.durationMs, userAgent,
          });

          emitGovernanceEvent({
            type: 'error', source: 'mcp', tool: name,
            blocked: false,
            details: `Timeout after ${outcome.durationMs}ms (limit: ${toolTimeoutMs}ms)`,
            apiKeyPrefix: apiKey?.substring(0, 12),
            durationMs: outcome.durationMs,
          });

          // ── AUDIT TRAIL (timeout) ──
          recordAudit(
            requestId, name, apiKey || 'anonymous', clientIp, userAgent,
            normalizedArgs, null, false, false, null, outcome.durationMs,
            `Timeout after ${outcome.durationMs}ms`,
          );

          return res.json({
            jsonrpc: '2.0', id,
            result: {
              content: [{
                type: 'text',
                text: JSON.stringify(enrichMCPResponse({
                  success: false,
                  error: 'TOOL_TIMEOUT',
                  error_code: 'TIMEOUT',
                  message: `Tool ${name} exceeded the ${toolTimeoutMs}ms execution limit. The operation may still be running in the background. Try again with simpler input, or use a faster tool variant.`,
                  tool: name,
                  timeout_ms: toolTimeoutMs,
                  elapsed_ms: outcome.durationMs,
                  retry_suggestion: SLOW_TOOLS.has(name)
                    ? 'This is a complex tool. Consider breaking the request into smaller pieces or using mode=quick if available.'
                    : 'This tool should normally complete within the timeout. The server may be under heavy load — retry in a few seconds.',
                }, { correlationId, toolName: name, args: normalizedArgs, isError: true })),
              }],
            },
          });
        }

        // Tool completed within timeout
        const result = outcome.result;
        const responseText = JSON.stringify(result);
        const durationMs = Date.now() - requestStart;

        // Record success in health probe telemetry
        recordToolExecution(name, durationMs, false, isBlockedResponse(responseText));

        logUsage({
          apiKey, ipAddress: clientIp, toolName: name, method: 'tools/call',
          success: true, responseTimeMs: durationMs,
          estimatedInputTokens: estimateTokens(JSON.stringify(params || {})),
          estimatedOutputTokens: estimateTokens(responseText),
          userAgent,
        });

        emitGovernanceEvent({
          type: isBlockedResponse(responseText) ? 'block' : 'approval',
          source: 'mcp', tool: name,
          score: extractScore(responseText),
          blocked: isBlockedResponse(responseText),
          details: `${name} via MCP (${durationMs}ms)`,
          apiKeyPrefix: apiKey?.substring(0, 12),
          durationMs,
        });

        generalLog.info(`[MCP] ${requestId} tools/call ${name} completed in ${durationMs}ms blocked=${isBlockedResponse(responseText)}`);

        // ── AUDIT TRAIL ──
        recordAudit(
          requestId, name, apiKey || 'anonymous', clientIp, userAgent,
          normalizedArgs, result, true, isBlockedResponse(responseText),
          // @ts-ignore — argument type mismatch (interface drift)
          extractScore(responseText), durationMs,
        );

        // Enrich successful response with governance metadata
        const enrichedResult = typeof result === 'object' && result !== null && 'content' in (result as EnrichedResult)
          ? {
              ...(result as EnrichedResult),
              content: (result as EnrichedResult).content?.map((c: { type: string; text: string }) => {
                if (c.type === 'text' && typeof c.text === 'string') {
                  try {
                    const parsed = JSON.parse(c.text);
                    const enriched = enrichMCPResponse(parsed, {
                      correlationId,
                      toolName: name,
                      args: normalizedArgs,
                      isError: false,
                    });
                    return { ...c, text: JSON.stringify(enriched) };
                  } catch { return c; }
                }
                return c;
              }),
            }
          : result;

        return res.json({ jsonrpc: '2.0', id, result: enrichedResult });
      }

      default:
        generalLog.warn(`[MCP] ${requestId} unknown method: ${method}`);
        return res.json({ jsonrpc: '2.0', id, error: { code: -32601, message: `Method not found: ${method}` } });
    }
  } catch (error: unknown) {
    generalLog.error('[MCP v2] Error:', error);
    if (error instanceof Error && error.stack) {
      generalLog.error('[MCP v2] FULL STACK TRACE:', error.stack);
    }

    const apiKey = (req as Request & { apiKey?: string }).apiKey;
    const toolName = req.body?.method === 'tools/call' ? (req.body?.params?.name || 'unknown') : (req.body?.method || 'unknown');
    // Record error in health probe telemetry
    recordToolExecution(toolName, Date.now() - requestStart, false, true);
    logUsage({
      apiKey, ipAddress: clientIp, toolName, method: req.body?.method || 'unknown',
      success: false, errorMessage: error instanceof Error ? error.message : 'Internal error',
      responseTimeMs: Date.now() - requestStart, userAgent,
    });

    emitGovernanceEvent({
      type: 'error', source: 'mcp', tool: toolName,
      blocked: false,
      details: error instanceof Error ? error.message : 'Internal error',
      apiKeyPrefix: apiKey?.substring(0, 12),
      durationMs: Date.now() - requestStart,
    });

    // Classify 503 cause and enrich error response
    const classified = classify503Cause(error instanceof Error ? error : String(error), toolName);
    const statusCode = classified.cause === 'circuit_breaker_open' || classified.cause === 'memory_pressure' ? 503 : 500;
    if (classified.retry_after_ms) {
      res.setHeader('Retry-After', Math.ceil(classified.retry_after_ms / 1000).toString());
    }
    res.status(statusCode).json({
      jsonrpc: '2.0', id: req.body?.id,
      error: {
        code: -32603,
        message: error instanceof Error ? error.message : 'Internal error',
        data: {
          cause: classified.cause,
          description: classified.description,
          recoverable: classified.recoverable,
          retry_after_ms: classified.retry_after_ms,
          correlation_id: correlationId,
        },
      },
    });
  }
});

// ============================================================================
// HEALTH CHECK (unauthenticated) — delegates to mcp-health-probe.ts
// Old basic health moved to /health/basic; full aggregated health at /health
// ============================================================================

import { computeHealthStatus, getMCPPerformanceMetrics } from './mcp-health-probe';
import { getCoverageSnapshot, getCoverageSummary } from '../governance/coverage-tracker';
import { getTelemetryStreams, getTelemetrySummary } from '../governance/telemetry-streams';

mcpRouterV2.get('/health', (_req: Request, res: Response) => {
  ensureServerInitialized();
  const start = Date.now();
  try {
    const health = computeHealthStatus();
    const coverageSnapshot = getCoverageSnapshot();
    const responseTimeMs = Date.now() - start;
    const httpStatus = health.status === 'critical' ? 503 : 200;
    res.status(httpStatus).json({
      ...health,
      // Include basic info for backward compatibility
      name: GRAVITO_MCP_SERVER_NAME,
      transport: 'http',
      tools_count: ALL_TOOLS.length,
      auth: AUTH_METADATA,
      timeout_config: {
        default_ms: DEFAULT_TOOL_TIMEOUT_MS,
        slow_tool_ms: SLOW_TOOL_TIMEOUT_MS,
        slow_tools_count: SLOW_TOOLS.size,
      },
      governance_coverage: coverageSnapshot,
      telemetry_streams: getTelemetryStreams(),
      responseTimeMs,
    });
  } catch (error: unknown) {
    generalLog.error('[MCP v2] Health probe failed:', error);
    res.status(500).json({ status: 'critical', error: 'Health probe internal error', timestamp: Date.now() });
  }
});

mcpRouterV2.get('/health/performance', (_req: Request, res: Response) => {
  try {
    const metrics = getMCPPerformanceMetrics();
    res.json({ tools: metrics, timestamp: Date.now() });
  } catch (error: unknown) {
    res.status(500).json({ error: 'Performance probe failed' });
  }
});

mcpRouterV2.get('/health/preflight', (_req: Request, res: Response) => {
  const { useFallback, reason } = shouldUseFallbackMode();
  res.json({ useFallback, reason, mode: useFallback ? 'heuristic-only' : 'full-governance', timestamp: Date.now() });
});

// Dedicated telemetry endpoint — lightweight, no auth, for dashboards
