  enhancedDetectMoment,
  enhancedAnalyzeContent,
} from './enhanced-tools';

const generalLog: GravitoLogger = createLogger('mcp');

// ============================================================================
// TYPES
// ============================================================================

export interface MCPContent {
  content: Array<{ type: string; text: string }>;
}

export interface ExecutionContext {
  apiKey?: string;
  clientIp?: string;
  userAgent?: string;
  /**
   * TRUSTED authenticated tenant, resolved by the HTTP handler from a validated
   * inference credential (provisioned tenant key → org-<id>/user-<id>, spoof-
   * proof). Additive + optional: existing call sites compile unchanged and leave
   * it undefined. It is the ONLY input that can raise the canonical verdict
   * receipt's tenant binding to `authenticated_tenant`.
   */
  authenticatedTenant?: { tenantId: string; source: string };
}

// Tool arguments arrive as parsed JSON from JSON-RPC — untyped at the boundary.
// Each handler validates its own inputs. This is the explicit trust boundary.
type ToolArgs = Record<string, unknown>;
type ToolHandler = (args: ToolArgs, ctx: ExecutionContext) => Promise<MCPContent>;

// ============================================================================
// HELPER: Wrap result in MCP content format
// ============================================================================

function mcpText(data: unknown): MCPContent {
  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
}

/** Safe wrapper — catches errors and returns them as standardized MCP content */
async function safeTool(fn: () => Promise<MCPContent>, toolName?: string): Promise<MCPContent> {
  try {
    return await fn();
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    const errorCode = classifyError(error);
    generalLog.error(`[ToolExecutor] ${toolName || 'unknown'} error (${errorCode}):`, error);
    return mcpText(mcpError(message || 'Tool execution failed', errorCode, toolName));
  }
}

// ============================================================================
// GOVERNANCE TOOLS
// ============================================================================

const governanceTools: Record<string, ToolHandler> = {
  reviewContent: async (args) => {
    const server = getGravitoMCPServer();
    // Normalize common parameter mismatches from MCP clients
    const normalized = { ...args } as Record<string, unknown>;
    // surface → surface_type
    if (normalized.surface && !normalized.surface_type) {
      normalized.surface_type = normalized.surface;
      delete normalized.surface;
    }
    // Default surface_type to 'marketing' if missing
    if (!normalized.surface_type) normalized.surface_type = 'marketing';
    // Default artifact_type to 'web_copy' if missing (valid: email|message|web_copy|doc|ad_copy)
    if (!normalized.artifact_type) normalized.artifact_type = 'web_copy';
    // Default to 'quick' mode for MCP calls — fast deterministic checks only.
    // Users can explicitly pass mode: 'release_gate' for full analysis.
    if (!normalized.mode) normalized.mode = 'quick';
    const result = await server.reviewContent(normalized as any);
    // Generate an approval_token when content passes review (not blocked)
    // This token can be passed to downstream tools to unlock gated operations
    if (result && typeof result === 'object' && !result.block_release) {
      try {
        const { getFailClosedGate } = await import('./fail-closed-gate');
        const gate = getFailClosedGate();
        const token = gate.createApprovalToken(
          (normalized.surface_type as string) || 'general',
          'reviewContent',
          true,
          [],
          (normalized.policy_preset as string) || 'default',
          false
        );
        (result as Record<string, unknown>).approval_token = token.tokenId;
      } catch (tokenErr) {
        // Non-fatal: proceed without token
      }
    }
    return mcpText(result);
  },

  governanceAudit: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.runGovernanceAudit(args as any));
  },

  verifyClaim: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.verifyClaim(args as any));
  },

  checkCompliance: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.checkCompliance(args as any));
  },

  getDecisionTrace: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getDecisionTrace(args as any));
  },

  getCapabilities: async () => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getCapabilities());
  },

  // --- Tools previously only in monolith, now explicit ---

  runGravito: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.runGravito(args as any));
  },

  buildGate: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.buildGate(args as any));
  },

  classifyClaims: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.classifyClaims(args as any));
  },

  requireEvidence: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.requireEvidence(args as any));
  },

  validateTruthSurface: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.validateTruthSurface(args as any));
  },

  getNexusOverview: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getNexusOverview(args as any));
  },

  getSurfaceMap: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getSurfaceMap(args as any));
  },

  recordOutcome: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.recordOutcome(args as any));
  },

  getRiskHeatmap: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getRiskHeatmap(args as any));
  },

  getOutcomeLift: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getOutcomeLift(args as any));
  },

  checkStructuralIntegrity: async (args) => {
    const skipClaude = args?.quick === true || args?.skipClaude === true;
    const verbose = args?.verbose !== false;
    const surfaceFilter = args?.surface as string | undefined;

    if (skipClaude) {
      // Fast deterministic scan — uses validateStructuralIntegritySync
      const syncResult = validateStructuralIntegritySync();
      const filteredIssues = surfaceFilter
        ? syncResult.issues.filter(i => i.surface === surfaceFilter)
        : syncResult.issues;

      return mcpText({
        score: syncResult.score,
        totalIssues: syncResult.totalIssues,
        surfaceBreakdown: syncResult.surfaceBreakdown,
        breakdown: syncResult.breakdown,
        issues: filteredIssues,
        validatedAt: new Date().toISOString(),
        adapters: '8 surfaces: website, mcp_registry, api, documentation, messaging, source_code, infrastructure, project_docs',
      });
    }

    // Full Claude-powered analysis
    const result = await validateStructuralIntegrity({ skipClaude: false, verbose });
    const resultRecord = result as unknown as Record<string, unknown>;
    const allIssues = (resultRecord.issues as Array<{ surface?: string }>) || (result as StructuralIntegrityResult).allIssues || [];
    const filteredIssues = surfaceFilter
      ? allIssues.filter((i) => i.surface === surfaceFilter)
      : allIssues;

    return mcpText({
      score: result.overallScore ?? (resultRecord.score as number),
      totalIssues: result.totalIssues,
      surfaceScores: (result as StructuralIntegrityResult).surfaceScores || {},
      surfaceBreakdown: (resultRecord.surfaceBreakdown as unknown as Record<string, unknown>) || {},
      breakdown: (resultRecord.breakdown as unknown as Record<string, unknown>) || {},
      claudeAnalysis: (result as StructuralIntegrityResult).claudeAnalysis,
      issues: filteredIssues,
      validatedAt: (result as StructuralIntegrityResult).validatedAt || new Date().toISOString(),
      adapters: '8 surfaces: website, mcp_registry, api, documentation, messaging, source_code, infrastructure, project_docs',
    });
  },

  remediateStructuralIssues: async (args) => {
    const { runStructuralRemediation } = await import('../governance/structural-auto-remediation');
    const mode = args?.mode === 'apply' ? 'apply' as const : 'dry_run' as const;
    const surfaces = args?.surfaces as string[] | undefined;
    const useClaude = args?.useClaude !== false;
    const result = await runStructuralRemediation({ mode, surfaces, useClaude });
    return mcpText({
      runId: result.runId,
      mode: result.mode,
      totalIssuesScanned: result.totalIssuesScanned,
      counts: result.counts,
      scoreBefore: result.scoreBefore,
      scoreAfter: result.scoreAfter,
      surfaceBreakdown: result.surfaceBreakdown,
      claudeAnalysis: result.claudeAnalysis,
      durationMs: result.durationMs,
      proposals: result.proposals.slice(0, 20).map(p => ({
        id: p.id,
        surface: p.issue.surface,
        category: p.issue.category,
        action: p.action,
        confidence: p.confidence,
        description: p.description,
        status: p.status,
        targetFile: p.targetFile,
      })),
    });
  },

  previewStructuralRemediation: async (args) => {
    const { previewRemediation } = await import('../governance/structural-auto-remediation');
    const surfaces = args?.surfaces as string[] | undefined;
    const result = previewRemediation(surfaces);
    return mcpText(result);
  },

  checkStructuralThresholds: async () => {
    const { checkThresholds } = await import('../governance/structural-integrity-thresholds');
    const result = checkThresholds('manual');
    return mcpText(result);
  },

  getStructuralThresholds: async () => {
    const { getThresholds } = await import('../governance/structural-integrity-thresholds');
    return mcpText(getThresholds());
  },

  updateStructuralThreshold: async (args) => {
    const { updateThreshold } = await import('../governance/structural-integrity-thresholds');
    const surfaceId = args?.surfaceId as string;
    if (!surfaceId) return mcpText({ error: 'surfaceId is required' });
    const updates: Record<string, unknown> = {};
    if (args?.targetScore !== undefined) updates.targetScore = args.targetScore;
    if (args?.severity !== undefined) updates.severity = args.severity;
    if (args?.enabled !== undefined) updates.enabled = args.enabled;
    if (args?.maxIssues !== undefined) updates.maxIssues = args.maxIssues;
    const result = updateThreshold(surfaceId, unsafeCast(updates, "boundary cast"));
    if (!result) return mcpText({ error: `Surface '${surfaceId}' not found` });
    return mcpText({ success: true, threshold: result });
  },

  getStructuralTrend: async (args) => {
    const { getSurfaceTrend } = await import('../governance/structural-integrity-thresholds');
    const surfaceId = args?.surfaceId as string;
    if (!surfaceId) return mcpText({ error: 'surfaceId is required' });
    const lookback = (args?.lookback as number) || 5;
    return mcpText(getSurfaceTrend(surfaceId, lookback));
  },
};

// ============================================================================
// COMPLIANCE PACK TOOLS
// ============================================================================

const complianceTools: Record<string, ToolHandler> = {
  checkApprovedClaims: async (args) => mcpText(await checkApprovedClaims(args as any)),
  enforceDisclaimers: async (args) => mcpText(await enforceDisclaimers(args as any)),
