// ============================================================================
// OUTBOUND PACK TOOLS
// ============================================================================

const outboundTools: Record<string, ToolHandler> = {
  composeEmail: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.composeEmail(args as any));
  },
  reviewSequence: async (args) => mcpText(await reviewSequence(args as any)),
  checkPersonalization: async (args) => mcpText(await checkPersonalization(args as any)),
  enforceBrandVoice: async (args) => mcpText(await enforceBrandVoice(args as any)),
  trackReplyRate: async (args) => mcpText(await trackReplyRate(args as any)),
};

// ============================================================================
// FINANCE PACK TOOLS
// ============================================================================

const financeTools: Record<string, ToolHandler> = {
  reviewTradingThesis: async (args) => mcpText(await reviewTradingThesis(args as any)),
  reviewTradeProposal: async (args) => mcpText(await reviewTradeProposal(args as any)),
  reviewStrategyChange: async (args) => mcpText(await reviewStrategyChange(args as any)),
  trackTradingOutcome: async (args) => mcpText(await trackTradingOutcome(args as any)),
};

// ============================================================================
// AGENT RUNTIME PACK TOOLS
// ============================================================================

const agentRuntimeTools: Record<string, ToolHandler> = {
  validateToolCall: async (args) => mcpText(await validateToolCall(args as any)),
  detectPromptInjection: async (args) => mcpText(await detectPromptInjection(args as any)),
  enforceEscalation: async (args) => mcpText(await enforceEscalation(args as any)),
  routeModel: async (args) => mcpText(await routeModel(args as any)),
};

// ============================================================================
