      const { runNarrativeCoherenceAudit } = await import('../governance/narrative-coherence');
      return mcpText(await runNarrativeCoherenceAudit(adapter));
    } else if (args?.routes?.length) {
      return mcpText(await auditWebsiteRoutes(args.routes));
    }
    return mcpText(await auditGravitoWebsite());
  },

  quickNarrativeCheck: async (args) => {
    const surface = args?.surface || 'website';
